+    let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
+        package: package.clone(),
+        target_version: version.clone(),
+        reasons: vec![ReleaseInclusionReason::Changeset],
+    }])
+    .unwrap();
