/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, selection))
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has
/// no tag in the canonical [`crate::TagIndex`], each with
/// [`ReleaseInclusionReason::UnreleasedVersion`].
///
/// A non-empty `selections` restricts the roster to exactly those identities,
/// each of which must be unreleased and publishable. `None` means nothing is
/// unreleased.
pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        if version_is_tagged(tags, &package.id, version) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !entries.iter().any(|entry| &entry.package == selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> bool {
    tags.contains_tag(&tags.template(package).render(version).to_string())
        || tags.last_tag(package).is_some_and(|tag| &tag.version == version)
}

pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy a second time here, from raw git diffs, is exactly
/// the kind of duplicated logic that drifts: an earlier version of this
/// function did just that, understood only a direct changeset match, and
/// rejected every real release in this repository once a fixed-group cascade
/// (a case its reimplementation never learned) touched an unnamed sibling.
///
/// Instead, this function reads the committed decision back and confirms the
/// commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let changed = parse_name_status(&changed, &diff_tree_args)?;

    // The decision must be freshly authored as part of *this* commit, not a
    // stale leftover an earlier release already committed and this one never
    // touched -- otherwise a commit that changes nothing real could still
    // carry forward a prior, unrelated decision's authority.
    let decision_path_str = normalized_git_path(decision_path)?;
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A cheap, independent sanity check that this commit is a real version
    // application and not just a hand-crafted decision file: some real
    // changeset was actually consumed. The decision's own entries, not this
    // changeset's content, remain the sole authority verified below.
    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
    let consumed_a_changeset = changed
        .iter()
        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
    if !consumed_a_changeset {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::NoChangesetConsumed,
        });
    }

    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &decision_path_str,
    )?;
    let decision: ReleaseDecisionV1 =
        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
            if let Some(version) = found_version {
                versions.insert(pkg.id.clone(), version);
            } else {
                return Err(GraphError::Manifest(callisto_model::ManifestError::MissingField {
                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                    field: "version",
                }));
            }
        }
        Ok(versions)
    }

    pub fn initial_versions(&self) -> Result<Vec<(String, Version)>, GraphError> {
        let base = self.base_versions()?;
        Ok(base.into_iter().map(|(id, v)| (pre_json_key(&id), v)).collect())
    }

    /// Resolves stored baselines to their owners before applying the owners' native version grammars.
    pub fn resolve_pre_state(
        &self,
        state: callisto_model::format::PreState,
    ) -> Result<callisto_model::format::PreState, GraphError> {
        let raw_versions = state
            .initial_versions
            .iter()
            .map(|(key, version)| (key.clone(), version.raw().to_string()))
            .collect();
        self.resolve_pre_state_with_raw_versions(state, &raw_versions)
    }

    /// Resolves stored baselines using their original JSON spellings.
    pub fn resolve_pre_state_from_json(
        &self,
        state: callisto_model::format::PreState,
        original_json: &str,
    ) -> Result<callisto_model::format::PreState, GraphError> {
        let clean_json = original_json.strip_prefix('\u{FEFF}').unwrap_or(original_json);
        let value: serde_json::Value = serde_json::from_str(clean_json).map_err(|error| {
            GraphError::PreJson(callisto_model::format::PreJsonError::Malformed {
                message: error.to_string(),
            })
        })?;
        let raw_versions: indexmap::IndexMap<String, String> = value
            .get("initialVersions")
            .and_then(serde_json::Value::as_object)
            .into_iter()
            .flat_map(|values| values.iter())
            .filter_map(|(key, value)| value.as_str().map(|raw| (key.clone(), raw.to_string())))
            .collect();
        self.resolve_pre_state_with_raw_versions(state, &raw_versions)
    }

    fn resolve_pre_state_with_raw_versions(
        &self,
        state: callisto_model::format::PreState,
        raw_versions: &indexmap::IndexMap<String, String>,
    ) -> Result<callisto_model::format::PreState, GraphError> {
        assign_promoted_pre_keys(
            self.git_access(),
            &self.graph,
            &self.identity,
            &self.config.pre_json_path(),
            state,
            raw_versions,
        )
    }
}

/// The `pre.json` `initialVersions` key for `id`: its display id, so `cargo/foo` and `npm/foo` never share an entry.
pub fn pre_json_key(id: &PackageId) -> String {
    id.display_name()
}

/// `id`'s pinned pre-release baseline.
pub fn pre_initial_version<'a>(pre: &'a callisto_model::format::PreState, id: &PackageId) -> Option<&'a Version> {
    pre.initial_versions.get(&pre_json_key(id))
}

/// The one package among `candidates` whose canonical manifest existed at `rev`, if exactly one did: the owner
/// of anything recorded under their shared bare name at that point.
pub(crate) fn sole_owner_at<'p>(
    git: &GitAccess<'_>,
    rev: &str,
    candidates: &[&'p callisto_model::Package],
) -> Result<Option<&'p callisto_model::Package>, GraphError> {
    let mut owner = None;
    for pkg in candidates {
        let Some(manifest) = pkg.canonical_manifests().next() else {
            continue;
        };
        if git.path_exists_at(rev, &manifest.path).map_err(GraphError::Vcs)? {
            if owner.is_some() {
                return Ok(None);
            }
            owner = Some(*pkg);
        }
    }
    Ok(owner)
}

/// Resolves native baselines, attributing historical bare keys at the commit that added `pre.json`.
pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
    git: &GitAccess<'_>,
    graph: &D,
    identity: &IdentityIndex,
    pre_json: &std::path::Path,
    mut state: callisto_model::format::PreState,
    raw_versions: &indexmap::IndexMap<String, String>,
) -> Result<callisto_model::format::PreState, GraphError> {
    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
    let mut owners = BTreeMap::new();
    for key in &keys {
        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
            owners.insert(key.clone(), owner);
            continue;
        }
        let same: Vec<&callisto_model::Package> = graph
            .packages()
            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
            .collect();
        let owner = if same.is_empty() {
            match identity.resolve(key) {
                Ok(id) => graph.packages().find(|p| p.id == id),
                Err(GraphError::UnknownPackage { .. }) => None,
                Err(GraphError::AmbiguousName { candidates, .. }) => {
                    return Err(GraphError::AmbiguousPreJsonKey {
                        key: key.clone(),
                        candidates,
                    });
                }
                Err(error) => return Err(error),
            }
        } else {
            let owner = match git.commit_adding(pre_json).map_err(GraphError::Vcs)? {
                Some(added) => sole_owner_at(git, &added, &same)?,
                None => None,
            };
            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
                key: key.clone(),
                candidates: same.iter().map(|p| p.id.clone()).collect(),
            })?)
        };
        if let Some(owner) = owner {
            owners.insert(key.clone(), owner);
        }
    }
    state
        .resolve_initial_versions_from_raw(raw_versions, |key| {
            owners
                .get(key)
                .and_then(|owner| owner.canonical_manifests().next().map(|manifest| manifest.ecosystem()))
        })
        .map_err(GraphError::PreJson)?;
    for key in keys {
        if let Some(owner) = owners.get(&key) {
            let owner_key = pre_json_key(&owner.id);
            if owner_key != key {
                if let Some(version) = state.initial_versions.shift_remove(&key) {
                    state.initial_versions.entry(owner_key).or_insert(version);
                }
            }
        }
    }
    Ok(state)
}

