use crate::{Ecosystem, Version, VersionGrammar};
use indexmap::IndexMap;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct PreState {
    pub mode: PreMode,
    pub tag: String,
    #[schemars(with = "std::collections::BTreeMap<String, Version>")]
    pub initial_versions: IndexMap<String, Version>,
    pub changesets: Vec<String>,
}

impl PreState {
    pub fn entering(tag: impl Into<String>, initial_versions: impl IntoIterator<Item = (String, Version)>) -> Self {
        let mut map = IndexMap::new();
        for (pkg, ver) in initial_versions {
            map.entry(pkg).or_insert(ver);
        }
        PreState {
            mode: PreMode::Pre,
            tag: tag.into(),
            initial_versions: map,
            changesets: Vec::new(),
        }
    }

    pub fn exiting(mut self) -> Self {
        self.mode = PreMode::Exit;
        self
    }

    /// Applies each baseline owner's native grammar; unresolved entries retain their parsed value.
    pub fn resolve_initial_versions(
        &mut self,
        mut ecosystem_for: impl FnMut(&str) -> Option<Ecosystem>,
    ) -> Result<(), PreJsonError> {
        let raw_versions = self
            .initial_versions
            .iter()
            .map(|(key, version)| (key.clone(), version.raw().to_string()))
            .collect();
        self.resolve_initial_versions_from_raw(&raw_versions, &mut ecosystem_for)
    }

    /// Validates the original wire spelling after each baseline owner is known.
    pub fn resolve_initial_versions_from_raw(
        &mut self,
        raw_versions: &IndexMap<String, String>,
        mut ecosystem_for: impl FnMut(&str) -> Option<Ecosystem>,
    ) -> Result<(), PreJsonError> {
        for (package, version) in &mut self.initial_versions {
            if let Some(ecosystem) = ecosystem_for(package) {
                let raw = raw_versions.get(package).map(String::as_str).unwrap_or(version.raw());
                *version = Version::parse_for_ecosystem(raw, ecosystem).map_err(|source| {
                    PreJsonError::InvalidInitialVersion {
                        package: package.clone(),
                        raw: raw.to_string(),
                        source,
                    }
                })?;
            }
        }
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum PreMode {
    Pre,
    Exit,
}

pub fn parse_pre_json(input: &str) -> Result<PreState, PreJsonError> {
    let clean_input = input.strip_prefix('\u{FEFF}').unwrap_or(input);
    let val: serde_json::Value =
        serde_json::from_str(clean_input).map_err(|e| PreJsonError::Malformed { message: e.to_string() })?;

    let obj = val.as_object().ok_or_else(|| PreJsonError::Malformed {
        message: "expected a JSON object".to_string(),
    })?;

    let mode_val = obj.get("mode").ok_or(PreJsonError::MissingField { field: "mode" })?;
    let mode_str = mode_val
        .as_str()
        .ok_or(PreJsonError::WrongFieldType { field: "mode" })?;
    let mode = match mode_str {
        "pre" => PreMode::Pre,
        "exit" => PreMode::Exit,
        _ => {
            return Err(PreJsonError::InvalidMode {
                found: mode_str.to_string(),
            })
        }
    };

    let tag_val = obj.get("tag").ok_or(PreJsonError::MissingField { field: "tag" })?;
    let tag = tag_val
        .as_str()
        .ok_or(PreJsonError::WrongFieldType { field: "tag" })?
        .to_string();

    let init_val = obj.get("initialVersions").ok_or(PreJsonError::MissingField {
        field: "initialVersions",
    })?;
    let init_obj = init_val.as_object().ok_or(PreJsonError::WrongFieldType {
        field: "initialVersions",
    })?;

    let mut initial_versions = IndexMap::new();
    for (pkg, v_val) in init_obj {
        let v_str = v_val.as_str().ok_or(PreJsonError::WrongFieldType {
            field: "initialVersions",
        })?;
        let ver = Version::parse(v_str, VersionGrammar::SemVer)
            .or_else(|_| Version::parse(v_str, VersionGrammar::Pep440))
            .map_err(|source| PreJsonError::InvalidInitialVersion {

item.stdout:
        });
    }

    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &decision_path_str,
    )?;
    let decision: ReleaseDecisionV1 =
        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
            path: decision_path.to_path_buf(),
            message: error.to_string(),
        })?;
    let claimed = decision
        .entries
        .iter()
        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();

    let changed_paths = changed
        .iter()
        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
        .collect::<std::collections::BTreeSet<_>>();

    // Every canonical manifest path this workspace currently declares, in
    // the exact order `workspace.graph.packages()` and
    // `Package::canonical_manifests()` yield -- both are backed by ordered
    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
    // the second traversal below visits the same (package, manifest) pairs
    // in the same order. That lets it zip the batched `before`/`after`
    // results back on by position instead of re-keying by path, which would
    // misbehave if two packages ever declared an identical manifest path.
    let manifest_queries: Vec<(String, Ecosystem)> = workspace
        .graph
        .packages()
        .flat_map(Package::canonical_manifests)
        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
        .collect::<Result<_, GraphError>>()?;
    let mut query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
    if manifest_queries
        .iter()
        .any(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
        && !query_paths.contains(&"Cargo.toml")
    {
        query_paths.push("Cargo.toml");
    }

    // Exactly two `git cat-file --batch` subprocess invocations total (one
    // per commit), regardless of how many canonical manifests the
    // workspace has -- replaces what was previously 2*N separate `git
    // show` spawns (one `manifest_version_at` call per manifest per
    // commit).
    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
    let after_blobs =
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before_versions = resolve_batch_versions(before_blobs, &query_paths, &manifest_queries)?;
    let after_versions = resolve_batch_versions(after_blobs, &query_paths, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            let changelog = normalized_git_path(changelog)?;
            if !changed_paths.contains(changelog.as_str()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for id in package_ids {
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before.version != after.version;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || &after.version != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });
                    }
                }
            }
        }
    }
    }
    if observed.len() != claimed.len() {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
        });
    }

    Ok(decision)
}

fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
        if changeset_dir.is_empty() {
            Some(path)
        } else {
            path.strip_prefix('/')
        }
    }) else {
        return false;
    };

    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
/// exited non-zero, carrying its real exit status and stderr instead of
/// discarding them.
fn command_non_zero_exit(program: &str, args: &[&str], output: &callisto_model::CommandOutput) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: output.exit_code,
            stderr: output.stderr.clone(),
        },
    }
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
/// output could not be parsed into the shape this module expects.
fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::MalformedOutput { detail: detail.into() },
    }
}

fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
    let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
    if !output.success() {
        return Err(command_non_zero_exit("git", args, &output));
    }
    Ok(output.stdout_trimmed().to_string())
}

fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
    output
        .lines()
        .map(|line| {
            let (status, path) = line.split_once('\t').ok_or_else(|| {
                command_malformed_output(
                    "git",
                    args,
                    format!("name-status line missing a tab separator: `{line}`"),
                )
            })?;
            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
                return Err(command_malformed_output(
                    "git",
                }
            }
        }
    };
    let head = head.as_str();

    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
    let pre_mode = {
        let path = ws.root.join(ws.config.pre_json_path());
        if path.exists() {
            let text =
                std::fs::read_to_string(&path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
            let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
            Some(state.mode)
        } else {
            None
        }
    };
    let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);

    let staged_manifests = if in_pre_release_cycle {
        BTreeSet::new()
    } else {
        canonical_manifest_staged_paths(ws)?
    };
    let pending = !in_pre_release_cycle
        && (head_has_pending_changeset(ws, head)?
            || working_tree_has_pending_changeset(ws)?
            || !staged_manifests.is_empty());
    if !pending {
        return Ok(());
    }

    let cargo_root = if ws
        .graph
        .packages()
        .flat_map(|pkg| pkg.canonical_manifests())
        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
    {
        manifest_blob_at(ws, head, "Cargo.toml")?
    } else {
        None
    };
    let cargo_index_needed = !staged_manifests.is_empty()
        && ws.graph.packages().any(|pkg| {
            pkg.canonical_manifests()
                .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
        });
    let cargo_root_index = if cargo_index_needed {
        manifest_blob_in_index(ws, "Cargo.toml")?.or_else(|| cargo_root.clone())
    } else {
        None
    };
    let base_versions = ws.base_versions()?;
    for pkg in ws.graph.packages() {
        let Some(disk) = base_versions.get(&pkg.id) else {
            continue;
        };
        for decl in pkg.canonical_manifests() {
            let path = super::release_decision::normalized_git_path(&decl.path)?;
            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
                continue;
            };
            let index_path_changed = staged_manifests.contains(&path)
                || (decl.ecosystem() == callisto_model::Ecosystem::Cargo && staged_manifests.contains("Cargo.toml"));
            let index_version = if index_path_changed {
                manifest_version_in_index(ws, &path, cargo_root_index.as_deref())?
            } else {
                None
            };
            let index_display = match &index_version {
                Some(version) => version.version.render().to_string(),
                None if index_path_changed => "absent".to_string(),
                None => head_version.version.render().to_string(),
            };
            let index_differs = index_path_changed
                && index_version
                    .as_ref()
                    .is_none_or(|version| version.version != head_version.version);
            let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
                && disk.is_prerelease()
                && (!index_path_changed
                    || index_version
                        .as_ref()
                        .is_some_and(|version| version.version.is_prerelease()));
            if completing_prerelease {
                continue;
            }
            if *disk != head_version.version || index_differs {
                return Err(GraphError::PartialVersionRun {
                    path: head_version.authority,
                    disk: disk.clone(),
                    index: index_display,
                    head: head_version.version,
                });
            }
        }
    }

    Ok(())
}

/// True when an untracked or tracked changeset remains in the configured directory on disk.
fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
) -> Result<bool, GraphError> {
    let dir = ws.root.join(&ws.config.changesets_dir);
    let entries = match std::fs::read_dir(&dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => {
            return Err(GraphError::ApplyIo {
                path: ws.config.changesets_dir.clone(),
                message: error.to_string(),
            })
        }
    };
    for entry in entries {
        let entry = entry.map_err(|error| GraphError::ApplyIo {
            path: ws.config.changesets_dir.clone(),
            message: error.to_string(),
        })?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        let is_file = entry.file_type().map_err(|error| GraphError::ApplyIo {
            path: ws.config.changesets_dir.join(&*name),
            message: error.to_string(),
        })?;
        if is_file.is_file() && name.ends_with(".md") && name != "README.md" {
            return Ok(true);
        }
    }
    Ok(false)
}

